+++ b/src/main/java/com/acme/payments/PaymentService.java
@@ -30,16 +30,21 @@ public class PaymentService {

     // Authorizes a card payment. Called by PaymentController for every checkout.
-    @Transactional
+    // No method-level @Transactional: remote calls must never run while a
+    // pooled DB connection is checked out. Each repository save below runs
+    // in its own short transaction and releases the connection at once.
