@SpringBootTest
class PaymentServicePoolRegressionTest {

    @Autowired PaymentService paymentService;
    @MockBean PaymentRepository paymentRepository;
    @MockBean FraudClient fraudClient;
    @MockBean PaymentGateway gateway;

    @Test
    void authorize_doesNotHoldDbTransactionDuringFraudCall() {
        AtomicBoolean txActiveDuringFraud = new AtomicBoolean(true);
        AtomicBoolean txActiveDuringGateway = new AtomicBoolean(true);
        when(paymentRepository.save(any())).thenAnswer(inv -> inv.getArgument(0));
        when(fraudClient.score(any())).thenAnswer(inv -> {
            txActiveDuringFraud.set(
                TransactionSynchronizationManager.isActualTransactionActive());
            return new FraudVerdict(false, null, 10);
        });
        when(gateway.authorize(any())).thenAnswer(inv -> {
            txActiveDuringGateway.set(
                TransactionSynchronizationManager.isActualTransactionActive());
            return new PaymentResult("ref-1", PaymentStatus.APPROVED);
        });

        paymentService.authorize(new AuthorizeRequest("ord_test", "10.00"));

        // Before the fix this is true: the fraud/gateway calls run inside
        // authorize()'s @Transactional boundary and pin a Hikari connection.
        assertFalse(txActiveDuringFraud.get(),
            "fraud call must not run inside a DB transaction");
        assertFalse(txActiveDuringGateway.get(),
            "gateway call must not run inside a DB transaction");
    }
}

